(window.TIMELINE_TRANSLATIONS=window.TIMELINE_TRANSLATIONS||{})["sw"]={"qin-dynasty":{"id":"qin-dynasty","title":"Nasaba ya Qin","summary":"Dola ya Qin iliwashinda wapinzani wake wakuu chini ya Ying Zheng, aliyechukua cheo cha kifalme cha Qin Shi Huang. Nasaba hiyo ilidumu kwa muda mfupi tu, lakini desturi zake za kijeshi na kiutawala ziliathiri himaya ya Han iliyofuata.","began":"Ushindi wa Qin ulifikia kilele kwa kuunganishwa kwa nchi, na Ying Zheng akajitangaza kuwa mfalme mkuu.","ended":"Nasaba hiyo ilianguka katika miaka iliyofuata kifo cha Qin Shi Huang; mamlaka shindani yalipigana kabla ya Han kuanzisha utawala wa kifalme.","why":"Iliunda mfumo wa kisiasa wa kifalme ambao nasaba za baadaye zilirekebisha."},"confucius":{"id":"confucius","title":"Konfusio afundisha utawala wa kimaadili","summary":"Konfusio alifundisha wakati wa Kipindi cha Masika na Vuli. Alisisitiza mwenendo wa kimaadili, wajibu wa kifamilia, kujifunza na wajibu wa mtawala kutawala kwa wema. Mafundisho yake yakawa mapokeo makubwa ya kifikra, na serikali za kifalme za baadaye ziliweka maandiko ya Konfusio katikati ya elimu rasmi.","why":"Mafundisho yake yaliunda maadili ya kisiasa, elimu na maadili ya familia kote Asia Mashariki."},"stonewall-riots":{"id":"stonewall-riots","title":"Uasi wa Stonewall","summary":"Wateja na wafuasi walipinga uvamizi wa polisi katika Stonewall Inn huko New York, na kufuatiwa na makabiliano na maandamano zaidi. Uasi huo ukawa kigezo muhimu cha rejea kwa vuguvugu lililokuwa likikua dhidi ya mateso ya wachache wa kijinsia.","why":"Stonewall ilisaidia kuchochea ukombozi wa mashoga na upangaji wa baadaye wa LGBTQ, ingawa haikuwa kitendo cha kwanza cha upinzani."}};
